import base64, hashlib, json, os, sys, time, traceback, urllib.request
from pathlib import Path

ROOT=Path(__file__).resolve().parent
STATE=ROOT/"daemon_state.json"
URL="https://raw.githubusercontent.com/8hatay9-commits/ibo/ad31b08280dbea26ad68454a3d45c20fe3cdaf48/flashbot/releases/v3.9.0/daemon.py"
BLOB_SHA1="67289d1f38bd3e4db9580948b02319436d78fd19"

def diag(obj):
    tmp=STATE.with_name(f"{STATE.name}.{os.getpid()}.v398.tmp")
    tmp.write_text(json.dumps(obj,indent=2),encoding="utf-8")
    tmp.replace(STATE)

worker="--worker" in sys.argv
if worker:
    diag({"ok":False,"version":"FLASHBOT-PRODUCTION-V3.9.8","mode":"DRY_RUN_ONLY","phase":"wrapper_worker_boot","last_error":None,"timestamp":time.time()})

try:
    raw=urllib.request.urlopen(URL,timeout=30).read()
    got=hashlib.sha1(f"blob {len(raw)}\\0".encode()+raw).hexdigest()
    if got!=BLOB_SHA1: raise RuntimeError(f"pinned V3.9.0 daemon mismatch: {got}")
    src=raw.decode("utf-8")
    src=src.replace("FLASHBOT-PRODUCTION-V3.8.4","FLASHBOT-PRODUCTION-V3.9.8")
    src=src.replace("FLASHBOT-SUPERVISOR-V3.8.4","FLASHBOT-SUPERVISOR-V3.9.8")
    old=base64.b64decode("ICAgIHJldHVybiBzcmMKCmRlZiBydW5fd29ya2VyKCk6Cg==").decode("utf-8")
    new=base64.b64decode("").decode("utf-8")
    if old not in src: raise RuntimeError("V3.9.8 patch_core return marker not found")
    src=src.replace(old,new,1)
    compile(src,URL,"exec")
    exec(compile(src,URL,"exec"),{"__name__":"__main__","__file__":str(Path(__file__).resolve())})
except BaseException as e:
    if worker:
        try:
            diag({"ok":False,"version":"FLASHBOT-PRODUCTION-V3.9.8","mode":"DRY_RUN_ONLY","phase":"wrapper_worker_error","last_error":f"{type(e).__name__}:{e}","traceback_tail":traceback.format_exc()[-4000:],"timestamp":time.time()})
        except Exception: pass
    raise
